from lib import *
L = lambda *a, **k: lesson(14, "A0", *a, **k)
A = "adjective"
L(1, "Ким ви працюєте?", "Назвати свою професію й спитати про чужу.",
 "What's your job? — «Ким ви працюєте?». У відповіді перед професією обов'язково a: I'm a driver. Українською артикля немає, тому його часто забувають.",
 [W("job", "/dʒɒb/", "noun", "робота, професія", "What's your job?", "Ким ви працюєте?"),
  W("driver", "/ˈdraɪvə/", "noun", "водій", "I'm a driver.", "Я водій."),
  W("cook", "/kʊk/", "noun", "кухар", "He's a cook.", "Він кухар."),
  W("nurse", "/nɜːs/", "noun", "медсестра, медбрат", "She's a nurse.", "Вона медсестра."),
  W("waiter", "/ˈweɪtə/", "noun", "офіціант", "My brother is a waiter.", "Мій брат офіціант."),
  W("builder", "/ˈbɪldə/", "noun", "будівельник", "He's a builder.", "Він будівельник."),
  W("manager", "/ˈmænɪdʒə/", "noun", "менеджер, керівник", "She's a manager.", "Вона менеджерка.")],
 [li("What is your boss like?", "Повторимо. Ваш начальник добрий. Що відповісти?", ["He's kind.", "He likes kind.", "He's a boss."], "He's kind."),
  mt([("driver", "водій"), ("cook", "кухар"), ("nurse", "медсестра"), ("waiter", "офіціант")], "Багато назв професій закінчуються на -er."),
  mt([("builder", "будівельник"), ("manager", "менеджер"), ("teacher", "учитель"), ("doctor", "лікар")], "Teacher і doctor ви вже знаєте."),
  liu("What's your job?", "Прослухайте. Що вас питають?", ["Ким ви працюєте", "Де ви працюєте", "Як ваші справи"], "Job — робота, професія."),
  fb("I'm ___ nurse.", ["a", "the", "my"], "Перед професією — a."),
  mc("Як правильно?", ["He's a builder.", "He's builder.", "He a builder."], "Потрібні і is, і a: He's a builder."),
  liu("My husband is a cook and I'm a waiter.", "Прослухайте. Ким працює чоловік?", ["Кухарем", "Офіціантом", "Водієм"], "A cook — кухар."),
  bs("Вона менеджерка.", ["She's", "a", "manager"], ["the", "is"], "She's a manager."),
  tr("Я водій.", ["I'm a driver", "I am a driver"], "I'm a driver."),
  li("What's your job?", "Ви працюєте офіціантом. Що відповісти?", ["I'm a waiter.", "I'm waiter.", "My job waiter."], "I'm a waiter.")])
L(2, "Я інженер", "Назвати професії, перед якими потрібне an.",
 "Перед професією на голосний звук — an: an engineer, an actor, an artist, an accountant, an electrician. Перед приголосним — a: a driver.",
 [W("engineer", "/ˌendʒɪˈnɪə/", "noun", "інженер", "I'm an engineer.", "Я інженер."),
  W("accountant", "/əˈkaʊntənt/", "noun", "бухгалтер", "She's an accountant.", "Вона бухгалтерка."),
  W("actor", "/ˈæktə/", "noun", "актор", "He's an actor.", "Він актор."),
  W("artist", "/ˈɑːtɪst/", "noun", "художник", "My aunt is an artist.", "Моя тітка художниця."),
  W("electrician", "/ɪˌlekˈtrɪʃn/", "noun", "електрик", "He's an electrician.", "Він електрик."),
  W("office worker", "/ˈɒfɪs ˌwɜːkə/", "noun", "офісний працівник", "I'm an office worker.", "Я офісний працівник.")],
 [fb("She's ___ nurse.", ["a", "an", "the"], "Nurse — з приголосного: a nurse.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("engineer", "інженер"), ("accountant", "бухгалтер"), ("actor", "актор"), ("artist", "художник"), ("electrician", "електрик")], "Усі ці слова починаються з голосного звука."),
  fb("I'm ___ engineer.", ["an", "a", "the"], "Engineer — з голосного: an."),
  fb("He's ___ manager.", ["a", "an", "is"], "Manager — з приголосного: a."),
  mc("Як правильно?", ["an office worker", "a office worker", "an driver"], "Office — з голосного: an office worker."),
  liu("My father is an electrician.", "Прослухайте. Ким працює тато?", ["Електриком", "Інженером", "Бухгалтером"], "An electrician — електрик."),
  liu("She's an accountant.", "Прослухайте. Ким вона працює?", ["Бухгалтеркою", "Акторкою", "Художницею"], "An accountant — бухгалтерка."),
  bs("Мій дядько актор.", ["My", "uncle", "is", "an", "actor"], ["a", "the"], "My uncle is an actor."),
  tr("Я інженер.", ["I'm an engineer", "I am an engineer"], "I'm an engineer."),
  li("What's your sister's job?", "Ваша сестра художниця. Що відповісти?", ["She's an artist.", "She's a artist.", "He's an artist."], "She's an artist.")])
L(3, "Де ви працюєте?", "Сказати, де і в кого ви працюєте.",
 "I work in… — про місце: I work in a hospital. I work for… — про роботодавця: I work for a big company. Перед hospital, hotel, factory — a; перед office — an.",
 [W("hospital", "/ˈhɒspɪtl/", "noun", "лікарня", "I work in a hospital.", "Я працюю в лікарні."),
  W("restaurant", "/ˈrestrɒnt/", "noun", "ресторан", "He works in a restaurant.", "Він працює в ресторані."),
  W("factory", "/ˈfæktri/", "noun", "завод, фабрика", "I work in a factory.", "Я працюю на заводі."),
  W("hotel", "/həʊˈtel/", "noun", "готель", "She works in a hotel.", "Вона працює в готелі."),
  W("warehouse", "/ˈweəhaʊs/", "noun", "склад", "I work in a warehouse.", "Я працюю на складі."),
  W("company", "/ˈkʌmpəni/", "noun", "компанія", "I work for a big company.", "Я працюю у великій компанії.")],
 [fb("I'm ___ accountant.", ["an", "a", "the"], "An accountant.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("hospital", "лікарня"), ("restaurant", "ресторан"), ("factory", "завод"), ("hotel", "готель")], "Місця роботи."),
  mt([("warehouse", "склад"), ("company", "компанія"), ("office", "офіс"), ("shop", "магазин")], "Ще місця роботи."),
  liu("I work in a factory.", "Прослухайте. Де працює людина?", ["На заводі", "На складі", "У лікарні"], "A factory — завод."),
  mcu("Де працює a nurse?", ["in a hospital", "in a warehouse", "in a factory"], "Медсестра працює в лікарні."),
  fb("I work ___ a hotel.", ["in", "on", "of"], "I work in a hotel."),
  fb("I work ___ a small company.", ["for", "on", "to"], "Work for — працювати на когось."),
  bs("Я працюю на складі.", ["I", "work", "in", "a", "warehouse"], ["for", "am"], "I work in a warehouse."),
  tr("Я працюю в лікарні.", ["I work in a hospital", "I work at a hospital"], "I work in a hospital."),
  li("Where do you work?", "Ви працюєте в ресторані. Що відповісти?", ["I work in a restaurant.", "I'm work restaurant.", "I'm a restaurant."], "I work in a restaurant.")])
L(4, "Чим ви займаєтеся?", "Розпитати про роботу й сказати, чи вона вам подобається.",
 "Питання про дії починають з do: What do you do? — «Чим ви займаєтеся?». Where do you work? Do you like your job? Коротка відповідь: Yes, I do або No, I don't.",
 [W("do", "/duː/", "verb", "робити; допоміжне слово в питаннях", "What do you do?", "Чим ви займаєтеся?"),
  W("boss", "/bɒs/", "noun", "начальник", "My boss is nice.", "Мій начальник приємний."),
  W("team", "/tiːm/", "noun", "команда", "I work in a team.", "Я працюю в команді."),
  W("interesting", "/ˈɪntrəstɪŋ/", A, "цікавий", "My job is interesting.", "Моя робота цікава."),
  W("boring", "/ˈbɔːrɪŋ/", A, "нудний", "It's boring.", "Це нудно."),
  W("hard", "/hɑːd/", A, "важкий, складний", "It's hard work.", "Це важка робота."),
  W("easy", "/ˈiːzi/", A, "легкий", "It isn't easy.", "Це нелегко.")],
 [fb("I work ___ a big company.", ["for", "on", "of"], "Work for.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("interesting", "цікавий"), ("boring", "нудний"), ("hard", "важкий"), ("easy", "легкий")], "Дві пари протилежних слів."),
  liu("What do you do?", "Прослухайте. Що вас питають?", ["Чим ви займаєтеся", "Що ви робите зараз", "Як ваші справи"], "What do you do? — питання про професію."),
  mc("Як спитати «Де ви працюєте?»", ["Where do you work?", "Where you work?", "Where are you work?"], "Питання про дію — з do."),
  fb("___ you like your job?", ["Do", "Are", "Is"], "Do you like…?"),
  fb("Do you like your job? — Yes, I ___.", ["do", "am", "like"], "Коротка відповідь: Yes, I do."),
  liu("My job is hard but interesting.", "Прослухайте. Яка робота?", ["Важка, але цікава", "Легка, але нудна", "Важка й нудна"], "Hard — важка, interesting — цікава."),
  bs("Чим ви займаєтеся?", ["What", "do", "you", "do"], ["are", "job"], "What do you do?"),
  tr("Моя робота цікава.", ["My job is interesting"], "My job is interesting."),
  li("Do you like your job?", "Робота вам не подобається, вона нудна. Що відповісти?", ["No, I don't. It's boring.", "No, I'm not. It's boring.", "No, I don't. It's interesting."], "No, I don't. It's boring.")])
L(5, "Він працює, вона не працює", "Розповісти про роботу іншої людини.",
 "З he і she до дієслова додають -s: I work → he works, she works. Заперечення: he doesn't work (уже без -s). Корисні слова: full-time — повний день, part-time — неповний.",
 [W("works", "/wɜːks/", "verb", "працює (з he, she)", "She works in a bank.", "Вона працює в банку."),
  W("doesn't", "/ˈdʌznt/", "verb", "не (з he, she)", "He doesn't work.", "Він не працює."),
  W("full-time", "/ˌfʊl ˈtaɪm/", A, "на повний день", "I work full-time.", "Я працюю повний день."),
  W("part-time", "/ˌpɑːt ˈtaɪm/", A, "на неповний день", "She works part-time.", "Вона працює неповний день."),
  W("unemployed", "/ˌʌnɪmˈplɔɪd/", A, "безробітний", "He's unemployed.", "Він безробітний."),
  W("retired", "/rɪˈtaɪəd/", A, "на пенсії", "My father is retired.", "Мій тато на пенсії.")],
 [li("What do you do?", "Повторимо. Ви медсестра. Що відповісти?", ["I'm a nurse.", "I do nurse.", "I'm fine."], "I'm a nurse."),
  mt([("full-time", "на повний день"), ("part-time", "на неповний день"), ("unemployed", "безробітний"), ("retired", "на пенсії")], "Слова про зайнятість."),
  fb("She ___ in a hospital.", ["works", "work", "working"], "З she — works."),
  fb("I ___ in a shop.", ["work", "works", "am work"], "З I — work, без -s."),
  fb("He ___ work on Sunday.", ["doesn't", "don't", "isn't"], "З he — doesn't."),
  liu("My wife works part-time.", "Прослухайте. Як працює дружина?", ["Неповний день", "Повний день", "Вона не працює"], "Part-time — неповний день."),
  liu("My grandfather doesn't work. He's retired.", "Прослухайте. Чому дідусь не працює?", ["Він на пенсії", "Він безробітний", "Він хворий"], "Retired — на пенсії."),
  bs("Він працює на заводі.", ["He", "works", "in", "a", "factory"], ["work", "for"], "He works in a factory."),
  tr("Вона не працює.", ["She doesn't work", "She does not work"], "She doesn't work."),
  li("What does your husband do?", "Ваш чоловік водій. Що відповісти?", ["He's a driver.", "He do a driver.", "She's a driver."], "He's a driver.")])
L(6, "Повторення: розмова про роботу", "Розповісти про свою роботу й розпитати співрозмовника.",
 "Нових слів немає. Повторюємо: I'm a… і I'm an…, I work in і I work for, питання з do, he works і he doesn't work.",
 [],
 [li("What do you do?", "Ви інженер. Що відповісти?", ["I'm an engineer.", "I'm a engineer.", "I do engineer."], "I'm an engineer."),
  fb("I work ___ a hospital. I'm a nurse.", ["in", "of", "on"], "I work in a hospital."),
  bs("Де ви працюєте?", ["Where", "do", "you", "work"], ["are", "does"], "Where do you work?"),
  tr("Я працюю повний день.", ["I work full-time", "I work full time"], "I work full-time."),
  liu("My sister is an accountant. She works for a big company.", "Прослухайте. Що ви дізналися про сестру?", ["Бухгалтерка у великій компанії", "Акторка у великій компанії", "Бухгалтерка в банку"], "An accountant, a big company."),
  fb("He ___ like his job. It's boring.", ["doesn't", "don't", "isn't"], "He doesn't like."),
  mc("Як сказати «Мій тато на пенсії»?", ["My father is retired.", "My father retired is.", "My father has retired job."], "My father is retired."),
  tr("Моя робота важка, але цікава.", ["My job is hard but interesting"], "My job is hard but interesting."),
  liu("Do you like your job? — Yes, I do. My team is great.", "Прослухайте. Чи подобається людині робота?", ["Так, у неї чудова команда", "Ні, команда погана", "Так, але начальник поганий"], "Yes, I do. My team is great."),
  li("Do you work full-time?", "Ви працюєте неповний день. Що відповісти?", ["No, I don't. I work part-time.", "No, I'm not. I work part-time.", "Yes, I work part-time."], "No, I don't. I work part-time.")],
 review=True)
